{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.wh_closing_inv_daily_base as SELECT _AIRBYTE_DATA:FACILITY::STRING AS FACILITY, _AIRBYTE_DATA:ITEM_SKUCODE::STRING AS ITEM_SKUCODE, COALESCE( TRY_TO_DATE(_AIRBYTE_DATA:CLOSING_DATE::STRING, \'DD-MM-YYYY\'), TRY_TO_DATE(_AIRBYTE_DATA:CLOSING_DATE::STRING, \'DD/MM/YYYY\'), TRY_TO_DATE(_AIRBYTE_DATA:CLOSING_DATE::STRING, \'YYYY-MM-DD\'), TRY_TO_DATE(LEFT(_AIRBYTE_DATA:CLOSING_DATE::STRING, 10), \'YYYY-MM-DD\'), TO_DATE(TRY_TO_TIMESTAMP(_AIRBYTE_DATA:CLOSING_DATE::STRING)) ) AS SNAPSHOT_DATE, TRY_TO_NUMBER(REPLACE(_AIRBYTE_DATA:INVENTORY::STRING, \',\', \'\')) AS INVENTORY, TRY_TO_NUMBER(REPLACE(_AIRBYTE_DATA:INVENTORY_BLOCKED::STRING, \',\', \'\')) AS INVENTORY_BLOCKED, TRY_TO_NUMBER(REPLACE(_AIRBYTE_DATA:INVENTORY_NOT_SYNCED::STRING, \',\', \'\')) AS INVENTORY_NOT_SYNCED, TRY_TO_NUMBER(REPLACE(_AIRBYTE_DATA:BAD_INVENTORY::STRING, \',\', \'\')) AS BAD_INVENTORY, TRY_TO_NUMBER(REPLACE(_AIRBYTE_DATA:STOCK_IN_TRANSFER::STRING, \',\', \'\')) AS STOCK_IN_TRANSFER, TRY_TO_NUMBER(REPLACE(_AIRBYTE_DATA:PUTAWAY_PENDING::STRING, \',\', \'\')) AS PUTAWAY_PENDING, TRY_TO_NUMBER(REPLACE(_AIRBYTE_DATA:PUTBACK_PENDING::STRING, \',\', \'\')) AS PUTBACK_PENDING, TRY_TO_NUMBER(REPLACE(_AIRBYTE_DATA:NOT_FOUND::STRING, \',\', \'\')) AS NOT_FOUND FROM SNITCH_DB.MAPLEMONK._AIRBYTE_RAW_WH_CLOSING_INVENTORY_DAYBYDAY UNION ALL SELECT _AIRBYTE_DATA:FACILITY::STRING AS FACILITY, _AIRBYTE_DATA:ITEM_SKUCODE::STRING AS ITEM_SKUCODE, COALESCE( TRY_TO_DATE(_AIRBYTE_DATA:DATE::STRING, \'YYYY-MM-DD\'), TRY_TO_DATE(_AIRBYTE_DATA:DATE::STRING, \'DD-MM-YYYY\')) AS SNAPSHOT_DATE, TRY_TO_NUMBER(REPLACE(_AIRBYTE_DATA:INVENTORY::STRING, \',\', \'\')) AS INVENTORY, TRY_TO_NUMBER(REPLACE(_AIRBYTE_DATA:INVENTORY_BLOCKED::STRING, \',\', \'\')) AS INVENTORY_BLOCKED, TRY_TO_NUMBER(REPLACE(_AIRBYTE_DATA:INVENTORY_NOT_SYNCED::STRING, \',\', \'\')) AS INVENTORY_NOT_SYNCED, TRY_TO_NUMBER(REPLACE(_AIRBYTE_DATA:BAD_INVENTORY::STRING, \',\', \'\')) AS BAD_INVENTORY, TRY_TO_NUMBER(REPLACE(_AIRBYTE_DATA:STOCK_IN_TRANSFER::STRING, \',\', \'\')) AS STOCK_IN_TRANSFER, TRY_TO_NUMBER(REPLACE(_AIRBYTE_DATA:PUTAWAY_PENDING::STRING, \',\', \'\')) AS PUTAWAY_PENDING, TRY_TO_NUMBER(REPLACE(_AIRBYTE_DATA:PUTBACK_PENDING::STRING, \',\', \'\')) AS PUTBACK_PENDING, TRY_TO_NUMBER(REPLACE(_AIRBYTE_DATA:NOT_FOUND::STRING, \',\', \'\')) AS NOT_FOUND FROM SNITCH_DB.MAPLEMONK._AIRBYTE_RAW_DAILY_INVENTORY; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.WH_CLOSING_INV_WEEKLY_SUMMARY AS WITH wh_min_dates AS ( SELECT DATE_TRUNC(\'week\', snapshot_date) AS week_start, item_skucode, MIN(snapshot_date) AS min_snapshot_date FROM snitch_db.maplemonk.wh_closing_inv_daily_base WHERE snapshot_date >= DATE \'2026-03-30\' GROUP BY 1, 2 ), wh_inv AS ( SELECT s.week_start, \'WH\' AS facility, CASE WHEN UPPER(b.item_skucode) LIKE \'4C-%\' OR UPPER(b.item_skucode) LIKE \'MP-%\' THEN SPLIT_PART(b.item_skucode, \'-\', 1) || \'-\' || SPLIT_PART(b.item_skucode, \'-\', 2) || \'-\' || SPLIT_PART(b.item_skucode, \'-\', 3) WHEN POSITION(\'-\' IN b.item_skucode) > 0 THEN SPLIT_PART(b.item_skucode, \'-\', 1) || \'-\' || SPLIT_PART(b.item_skucode, \'-\', 2) ELSE b.item_skucode END AS sku_group, b.item_skucode AS sku_code, SUM(b.inventory) AS inventory, SUM(b.inventory_not_synced) + SUM(b.stock_in_transfer) + SUM(b.putaway_pending) + SUM(b.putback_pending) AS wh_processing_inventory, SUM(b.not_found) AS not_found_inventory, SUM(b.bad_inventory) AS bad_inventory FROM snitch_db.maplemonk.wh_closing_inv_daily_base b INNER JOIN wh_min_dates s ON b.item_skucode = s.item_skucode AND b.snapshot_date = s.min_snapshot_date GROUP BY 1, 2, 3, 4 ), offline_base AS ( SELECT * FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE date >= \'2026-03-29\' AND DAYOFWEEKISO(date) = 1 ), onesize AS ( SELECT date AS week_start, UPPER(sku_group) AS sku_group, UPPER(sku_group) AS sku_code, COALESCE(inventory, 0) + COALESCE(jit_qty, 0) AS inventory FROM offline_base WHERE UPPER(sku_group) LIKE \'4MSFR%\' OR UPPER(sku_group) LIKE \'SN%\' OR UPPER(sku_group) LIKE \'BP%\' OR UPPER(sku_group) LIKE \'4MCP%\' ), sized_base AS ( SELECT * FROM offline_base WHERE NOT (UPPER(sku_group) LIKE \'4MSFR%\' OR UPPER(sku_group) LIKE \'SN%\' OR UPPER(sku_group) LIKE \'BP%\' OR UPPER(sku_group) LIKE \'4MCP%\') ), inv_unpivot AS ( SELECT date, branch_code, marketplace_mapped, UPPER(sku_group) AS sku_grp, CASE WHEN LOWER(sku_group) LIKE \'sh%\' THEN CASE REPLACE(size, \'_UNITS\', \'\') WHEN \'XS\' THEN \'40\' WHEN \'S\' THEN \'41\' WHEN \'M\' THEN \'42\' WHEN \'L\' THEN \'43\' WHEN \'XL\' THEN \'44\' WHEN \'XXL\' THEN \'45\' WHEN \'XL3\' THEN \'46\' WHEN \'XL4\' THEN \'47\' WHEN \'XL5\' THEN \'48\' ELSE REPLACE(size, \'_UNITS\', \'\') END WHEN UPPER(new_category) IN ( \'CARGO PANTS\',\'CHINOS\',\'JEANS\', \'JOGGERS & TRACKPANTS\',\'JOGGERS AND TRACKPANTS\', \'SHORTS\',\'TROUSERS\',\'BELTS\' ) THEN CASE REPLACE(size, \'_UNITS\', \'\') WHEN \'XS\' THEN \'28\' WHEN \'S\' THEN \'30\' WHEN \'M\' THEN \'32\' WHEN \'L\' THEN \'34\' WHEN \'XL\' THEN \'36\' WHEN \'XXL\' THEN \'38\' WHEN \'XL3\' THEN \'40\' WHEN \'XL4\' THEN \'42\' WHEN \'XL5\' THEN \'44\' WHEN \'XL6\' THEN \'46\' ELSE REPLACE(size, \'_UNITS\', \'\') END ELSE CASE REPLACE(size, \'_UNITS\', \'\') WHEN \'XL3\' THEN \'3XL\' WHEN \'XL4\' THEN \'4XL\' WHEN \'XL5\' THEN \'5XL\' WHEN \'XL6\' THEN \'6XL\' ELSE REPLACE(size, \'_UNITS\', \'\') END END AS size_out, COALESCE(units, 0) AS inv_units FROM sized_base UNPIVOT ( units FOR size IN ( xs_units, s_units, m_units, l_units, xl_units, xxl_units, xl3_units, xl4_units, xl5_units, xl6_units ) ) AS unpivoted_data ), jit_unpivot AS ( SELECT date, branch_code, marketplace_mapped, UPPER(sku_group) AS sku_grp, CASE WHEN LOWER(sku_group) LIKE \'sh%\' THEN CASE REPLACE(REPLACE(size, \'_UNITS\', \'\'), \'JIT_\', \'\') WHEN \'XS\' THEN \'40\' WHEN \'S\' THEN \'41\' WHEN \'M\' THEN \'42\' WHEN \'L\' THEN \'43\' WHEN \'XL\' THEN \'44\' WHEN \'2XL\' THEN \'45\' WHEN \'XXL\' THEN \'45\' WHEN \'3XL\' THEN \'46\' WHEN \'4XL\' THEN \'47\' WHEN \'5XL\' THEN \'48\' ELSE REPLACE(REPLACE(size, \'_UNITS\', \'\'), \'JIT_\', \'\') END WHEN UPPER(new_category) IN ( \'CARGO PANTS\',\'CHINOS\',\'JEANS\', \'JOGGERS & TRACKPANTS\',\'JOGGERS AND TRACKPANTS\', \'SHORTS\',\'TROUSERS\',\'BELTS\' ) THEN CASE REPLACE(REPLACE(size, \'_UNITS\', \'\'), \'JIT_\', \'\') WHEN \'XS\' THEN \'28\' WHEN \'S\' THEN \'30\' WHEN \'M\' THEN \'32\' WHEN \'L\' THEN \'34\' WHEN \'XL\' THEN \'36\' WHEN \'2XL\' THEN \'38\' WHEN \'XXL\' THEN \'38\' WHEN \'3XL\' THEN \'40\' WHEN \'4XL\' THEN \'42\' WHEN \'5XL\' THEN \'44\' WHEN \'6XL\' THEN \'46\' ELSE REPLACE(REPLACE(size, \'_UNITS\', \'\'), \'JIT_\', \'\') END ELSE CASE REPLACE(REPLACE(size, \'_UNITS\', \'\'), \'JIT_\', \'\') WHEN \'2XL\' THEN \'XXL\' ELSE REPLACE(REPLACE(size, \'_UNITS\', \'\'), \'JIT_\', \'\') END END AS size_out, COALESCE(units, 0) AS jit_units FROM sized_base UNPIVOT ( units FOR size IN ( jit_xs_units, jit_s_units, jit_m_units, jit_l_units, jit_xl_units, jit_2xl_units, jit_3xl_units, jit_4xl_units, jit_5xl_units, jit_6xl_units ) ) AS unpivoted_data ), sized_skus AS ( SELECT COALESCE(i.date, j.date) AS week_start, COALESCE(i.sku_grp, j.sku_grp) AS sku_group, CONCAT(COALESCE(i.sku_grp, j.sku_grp), \'-\', COALESCE(i.size_out, j.size_out)) AS sku_code, COALESCE(i.inv_units, 0) + COALESCE(j.jit_units, 0) AS inventory FROM inv_unpivot i FULL OUTER JOIN jit_unpivot j ON i.date = j.date AND i.branch_code = j.branch_code AND i.marketplace_mapped = j.marketplace_mapped AND i.sku_grp = j.sku_grp AND i.size_out = j.size_out WHERE COALESCE(i.inv_units, 0) + COALESCE(j.jit_units, 0) > 0 ), offline_raw AS ( SELECT week_start, sku_group, sku_code, inventory FROM sized_skus UNION ALL SELECT week_start, sku_group, sku_code, inventory FROM onesize WHERE inventory > 0 ), offline_inv AS ( SELECT week_start, \'OFFLINE\' AS facility, sku_group, sku_code, SUM(inventory) AS inventory, 0 AS wh_processing_inventory, 0 AS not_found_inventory, 0 AS bad_inventory FROM offline_raw GROUP BY 1, 2, 3, 4 ), combined_size_level AS ( SELECT week_start, sku_group, sku_code, inventory FROM wh_inv UNION ALL SELECT week_start, sku_group, sku_code, inventory FROM offline_inv ), sku_group_pivot AS ( SELECT week_start, sku_group, SUM(inventory) AS sellable_inventory, COALESCE(SUM(CASE WHEN UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'S\' OR (UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'30\' AND LOWER(sku_group) NOT LIKE \'sh%\') OR (UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'41\' AND LOWER(sku_group) LIKE \'sh%\') THEN inventory ELSE 0 END), 0) AS s_units, COALESCE(SUM(CASE WHEN UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'M\' OR (UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'32\' AND LOWER(sku_group) NOT LIKE \'sh%\') OR (UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'42\' AND LOWER(sku_group) LIKE \'sh%\') THEN inventory ELSE 0 END), 0) AS m_units, COALESCE(SUM(CASE WHEN UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'L\' OR (UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'34\' AND LOWER(sku_group) NOT LIKE \'sh%\') OR (UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'43\' AND LOWER(sku_group) LIKE \'sh%\') THEN inventory ELSE 0 END), 0) AS l_units, COALESCE(SUM(CASE WHEN UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'XL\' OR (UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'36\' AND LOWER(sku_group) NOT LIKE \'sh%\') OR (UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'44\' AND LOWER(sku_group) LIKE \'sh%\') THEN inventory ELSE 0 END), 0) AS xl_units, COALESCE(SUM(CASE WHEN UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'3XL\' OR (UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'40\' AND LOWER(sku_group) NOT LIKE \'sh%\') OR (UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'46\' AND LOWER(sku_group) LIKE \'sh%\') THEN inventory ELSE 0 END), 0) AS xl3_units, COALESCE(SUM(CASE WHEN UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'4XL\' OR (UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'42\' AND LOWER(sku_group) NOT LIKE \'sh%\') OR (UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'47\' AND LOWER(sku_group) LIKE \'sh%\') THEN inventory ELSE 0 END), 0) AS xl4_units, COALESCE(SUM(CASE WHEN UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'5XL\' OR (UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'44\' AND LOWER(sku_group) NOT LIKE \'sh%\') OR (UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'48\' AND LOWER(sku_group) LIKE \'sh%\') THEN inventory ELSE 0 END), 0) AS xl5_units, COALESCE(SUM(CASE WHEN UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'6XL\' OR (UPPER(SPLIT_PART(sku_code, \'-\', -1)) = \'46\' AND LOWER(sku_group) NOT LIKE \'sh%\') THEN inventory ELSE 0 END), 0) AS xl6_units FROM combined_size_level GROUP BY 1, 2 ), size_status AS ( SELECT week_start, sku_group, COALESCE(CASE WHEN UPPER(sku_group) LIKE \'4MSFR%\' THEN ROUND((sellable_inventory - 2) / 60, 0) WHEN UPPER(sku_group) LIKE \'SN%\' THEN ROUND((sellable_inventory - 1) / 20, 0) WHEN UPPER(sku_group) LIKE \'BP%\' THEN ROUND((sellable_inventory - 1) / 15, 0) WHEN UPPER(sku_group) LIKE \'4MCP%\' THEN ROUND((sellable_inventory - 1) / 15, 0) WHEN UPPER(sku_group) LIKE \'SH0%\' THEN GREATEST(LEAST(ROUND((s_units - 1) / 10), ROUND((m_units - 1) / 10), ROUND((l_units - 1) / 10), ROUND((xl_units - 1) / 10)), 0) WHEN UPPER(sku_group) LIKE \'4MBL%\' THEN GREATEST(LEAST(ROUND((m_units - 1) / 10), ROUND((xl_units - 1) / 10), ROUND((xl3_units - 1) / 10)), 0) WHEN UPPER(sku_group) LIKE \'4MBG%\' OR UPPER(sku_group) LIKE \'%4BJ002%\' OR UPPER(sku_group) LIKE \'4BRN%\' OR UPPER(sku_group) LIKE \'4BPL%\' OR UPPER(sku_group) LIKE \'4BTR%\' OR UPPER(sku_group) LIKE \'4BCH%\' OR UPPER(sku_group) LIKE \'4BJE%\' OR UPPER(sku_group) LIKE \'4BJK%\' OR UPPER(sku_group) LIKE \'4BSW%\' OR UPPER(sku_group) LIKE \'4BHD%\' OR UPPER(sku_group) LIKE \'4BOS%\' OR UPPER(sku_group) LIKE \'4BSHS%\' OR UPPER(sku_group) LIKE \'4BSFS%\' OR UPPER(sku_group) LIKE \'4BSH%\' OR UPPER(sku_group) LIKE \'4BBL%\' OR UPPER(sku_group) LIKE \'4BCA%\' OR UPPER(sku_group) LIKE \'4BSWT%\' OR UPPER(sku_group) LIKE \'4BCD%\' OR UPPER(sku_group) LIKE \'4BJO%\' THEN GREATEST(LEAST(ROUND((xl3_units - 1) / 15), ROUND((xl4_units - 1) / 15), ROUND((xl5_units - 1) / 10), ROUND((xl6_units - 1) / 10)), 0) ELSE GREATEST(LEAST(ROUND((s_units - 1) / 15), ROUND((m_units - 1) / 20), ROUND((l_units - 1) / 20), ROUND((xl_units - 1) / 15)), 0) END, 0) AS full_size_options FROM sku_group_pivot ), weekly_total_inv AS ( SELECT week_start, UPPER(TRIM(sku_code)) AS sku, SUM(inventory) AS total_inventory FROM combined_size_level GROUP BY 1, 2 HAVING SUM(inventory) > 0 ), po_data AS ( SELECT TO_DATE(PO_DATE, \'DD-MM-YYYY\') AS po_date, UPPER(TRIM(sku::STRING)) AS sku, SUM(PO_QTY) AS po_qty FROM SNITCH_DB.MAPLEMONK.S3_UC_PO WHERE TO_DATE(PO_DATE, \'DD-MM-YYYY\') IS NOT NULL GROUP BY 1, 2 ), po_by_week AS ( SELECT i.week_start, i.sku, i.total_inventory, p.po_date, p.po_qty, SUM(p.po_qty) OVER ( PARTITION BY i.week_start, i.sku ORDER BY p.po_date DESC ROWS UNBOUNDED PRECEDING ) AS cumulative_qty FROM weekly_total_inv i INNER JOIN po_data p ON i.sku = p.sku WHERE p.po_date <= i.week_start ), weekly_allocated AS ( SELECT week_start, sku, GREATEST(0, LEAST(po_qty, total_inventory - (cumulative_qty - po_qty))) AS allocated_qty, DATEDIFF(\'day\', po_date, week_start) AS days_old FROM po_by_week ), weekly_ageing AS ( SELECT week_start, sku, ROUND(SUM(allocated_qty * days_old) * 1.0 / NULLIF(SUM(allocated_qty), 0), 1) AS weighted_ageing_days FROM weekly_allocated WHERE allocated_qty > 0 GROUP BY 1, 2 ), cost_lookup AS ( SELECT UPPER(TRIM(\"Item SkuCode\")) AS sku, MAX(TRY_TO_NUMBER(NULLIF(TRIM(\"Cost Price\"::STRING), \'\'), 38, 2)) AS cost_price FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_LIVE_INVENTORY GROUP BY 1 ), combined AS ( SELECT week_start, facility, sku_group, sku_code, inventory, wh_processing_inventory, not_found_inventory, bad_inventory FROM wh_inv UNION ALL SELECT week_start, facility, sku_group, sku_code, inventory, wh_processing_inventory, not_found_inventory, bad_inventory FROM offline_inv ) SELECT c.week_start, c.facility, c.sku_group, c.sku_code, c.inventory, c.wh_processing_inventory, c.not_found_inventory, c.bad_inventory, COALESCE(s.full_size_options, 0) AS full_size_options, CASE WHEN COALESCE(s.full_size_options, 0) < 1 THEN \'CUT\' ELSE \'FULL\' END AS size_status, ROUND(a.weighted_ageing_days, 0) AS ageing, cl.cost_price, c.inventory * cl.cost_price AS total_cogs FROM combined c LEFT JOIN size_status s ON c.week_start = s.week_start AND c.sku_group = s.sku_group LEFT JOIN weekly_ageing a ON a.week_start = c.week_start AND a.sku = UPPER(TRIM(c.sku_code)) LEFT JOIN cost_lookup cl ON cl.sku = UPPER(TRIM(c.sku_code)) ORDER BY c.week_start, c.facility, c.sku_code; INSERT INTO snitch_db.maplemonk.wh_closing_inv_daily_base SELECT l.FACILITY, l.ITEM_SKUCODE, l.SNAPSHOT_DATE, l.INVENTORY, l.INVENTORY_BLOCKED, l.INVENTORY_NOT_SYNCED, l.BAD_INVENTORY, l.STOCK_IN_TRANSFER, l.PUTAWAY_PENDING, l.PUTBACK_PENDING, l.NOT_FOUND FROM ( SELECT FACILITY, \"Item SkuCode\" AS ITEM_SKUCODE, CURRENT_DATE AS SNAPSHOT_DATE, SUM(INVENTORY) AS INVENTORY, SUM(\"Inventory Blocked\") AS INVENTORY_BLOCKED, SUM(\"Inventory Not Synced\") AS INVENTORY_NOT_SYNCED, SUM(\"Bad Inventory\") AS BAD_INVENTORY, SUM(\"Stock In Transfer\") AS STOCK_IN_TRANSFER, SUM(\"Putaway Pending\") AS PUTAWAY_PENDING, SUM(\"Putback Pending\") AS PUTBACK_PENDING, SUM(\"Net Variance\") AS NOT_FOUND FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_LIVE_INVENTORY GROUP BY 1, 2 ) l WHERE NOT EXISTS ( SELECT 1 FROM snitch_db.maplemonk.wh_closing_inv_daily_base b WHERE b.FACILITY = l.FACILITY AND b.SNAPSHOT_DATE = l.SNAPSHOT_DATE );",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            